function uploadProgressMarkup() {
  if (!mediaUpload) return '';
  return `<section class="upload-progress upload-session" id="upload-progress" aria-label="Proses unggah media"><div class="upload-session-heading"><div><strong>Unggah media</strong><p id="upload-status" role="status"></p></div>${button('Batalkan unggahan','cancel-upload',{class:'small',icon:'x'})}</div><div class="upload-progress-label"><span id="upload-name">${e(mediaUpload.name)}</span><span id="upload-percent"></span></div><div class="progress" role="progressbar" aria-label="Progres unggah media" aria-valuemin="0" aria-valuemax="100"><span id="upload-bar"></span></div><p class="upload-session-hint">Batalkan untuk menghentikan file ini dan antrean berikutnya. File yang sudah selesai tetap tersimpan.</p></section>`;
}
function updateUploadProgress() {
  const job = mediaUpload;
  document.querySelectorAll('[data-action="upload-media"]').forEach(button => { button.disabled = Boolean(job); });
  const input = document.querySelector('#media-upload');
  if (input) input.disabled = Boolean(job);
  document.querySelector('#upload-zone')?.setAttribute('aria-busy', String(Boolean(job)));
  if (!job) { document.querySelector('#upload-progress')?.remove(); return; }
  if (!document.querySelector('#upload-progress')) document.querySelector('#main-content')?.insertAdjacentHTML('beforebegin', uploadProgressMarkup());
  const panel = document.querySelector('#upload-progress');
  if (!panel) return;
  panel.querySelector('#upload-name').textContent = job.name;
  panel.querySelector('#upload-percent').textContent = `${job.percent}%`;
  panel.querySelector('#upload-bar').style.width = `${job.percent}%`;
  panel.querySelector('[role="progressbar"]').setAttribute('aria-valuenow', job.percent);
  panel.querySelector('#upload-status').textContent = job.cancelled ? 'Membatalkan unggahan…' : job.finishing ? 'Menyelesaikan unggahan…' : `File ${job.index + 1} dari ${job.total}`;
  const cancel = panel.querySelector('[data-action="cancel-upload"]');
  cancel.disabled = job.cancelled;
  cancel.innerHTML = `${icon('x')}${job.cancelled ? 'Membatalkan…' : 'Batalkan unggahan'}`;
}
function cancelMediaUpload() {
  if (!mediaUpload || mediaUpload.cancelled) return;
  mediaUpload.cancelled = true;
  updateUploadProgress();
  mediaUpload.controller.abort();
}
function uploadFile(file, onProgress, signal) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    let settled = false;
    const aborted = () => new DOMException('Unggahan dibatalkan.', 'AbortError');
    const finish = (error, result) => {
      if (settled) return;
      settled = true;
      signal.removeEventListener('abort', cancel);
      if (error) reject(error); else resolve(result);
    };
    const cancel = () => { xhr.abort(); finish(aborted()); };
    if (signal.aborted) { finish(aborted()); return; }
    xhr.open('POST', '/api/media'); xhr.withCredentials = true;
    xhr.setRequestHeader('X-RJ-Request', '1'); xhr.setRequestHeader('X-Filename', encodeURIComponent(file.name));
    xhr.setRequestHeader('Content-Type', file.type || 'application/octet-stream');
    xhr.upload.onprogress = event => { if (event.lengthComputable && !signal.aborted) onProgress(Math.round(event.loaded / event.total * 100)); };
    xhr.onload = () => {
      let result; try { result = JSON.parse(xhr.responseText); } catch { result = {}; }
      finish(xhr.status >= 200 && xhr.status < 300 ? null : new Error(result.error || 'Unggahan gagal.'), result);
    };
    xhr.onerror = () => finish(new Error('Koneksi terputus saat mengunggah.'));
    xhr.onabort = () => finish(aborted());
    signal.addEventListener('abort', cancel, { once: true });
    try { xhr.send(file); } catch (error) { finish(error); }
  });
}
async function uploadFiles(files) {
  if (!files.length) return;
  if (mediaUpload) { toast('Unggahan masih berjalan. Selesaikan atau batalkan unggahan terlebih dahulu.'); return; }
  const job = { controller: new AbortController(), cancelled: false, name: files[0].name, index: 0, total: files.length, percent: 0, finishing: false };
  mediaUpload = job; updateUploadProgress();
  try {
    for (const [index, file] of files.entries()) {
      if (job.cancelled) break;
      Object.assign(job, { name: file.name, index, percent: 0, finishing: false }); updateUploadProgress();
      try {
        await uploadFile(file, percent => {
          if (mediaUpload !== job || job.cancelled) return;
          job.percent = Math.min(99, percent); job.finishing = percent >= 100; updateUploadProgress();
        }, job.controller.signal);
        toast(`${file.name} berhasil diunggah.`);
      } catch (error) {
        if (job.cancelled || error.name === 'AbortError') break;
        report(error);
      }
    }
    if (job.cancelled) toast('Unggahan dibatalkan. File yang sudah selesai tetap tersimpan.');
  } finally {
    if (mediaUpload === job) mediaUpload = null;
    updateUploadProgress();
    try {
      await refresh(false);
      if (!S.editor && S.view === 'media' && !modal.open && !previewModal.open) render();
    } catch (error) { report(error); }
  }
}
function bindDropZone(){updateConnection();const zone=document.querySelector('#upload-zone');if(!zone)return;zone.addEventListener('dragover',event=>{event.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',event=>{event.preventDefault();zone.classList.remove('dragging');uploadFiles([...event.dataTransfer.files]).catch(report);});}
