async function downloadBackup(){const response=await fetch('/api/backup',{credentials:'same-origin'});if(!response.ok){const result=await response.json().catch(()=>({}));throw new Error(result.error||'Backup gagal dibuat.');}const blob=await response.blob();downloadBlob(blob,`RJ-Signage-backup-${new Date().toISOString().slice(0,10)}.json`);toast('Backup selesai diunduh. Simpan salinannya di perangkat lain.');}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=name;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function restoreFromFile(file){if(file.size>256*1024*1024)throw new Error('Paket terlalu besar untuk dipulihkan melalui dashboard. Hubungi pengelola server.');let archive;try{archive=JSON.parse(await file.text());}catch{throw new Error('Berkas backup bukan JSON yang valid.');}openModal('Pulihkan backup','Pemulihan mengganti layout, media, jadwal, dan pengaturan.',`<div class="notice warning">File: <strong>${e(file.name)}</strong><br>${bytes(file.size)}. Cadangan pengaman dibuat sebelum pemulihan. Akun admin dan identitas player saat ini dipertahankan.</div><div class="field"><label for="restore-confirm">Ketik PULIHKAN untuk melanjutkan</label><input id="restore-confirm" name="confirm" required pattern="PULIHKAN" autocomplete="off" placeholder="PULIHKAN"></div>`,'Pulihkan backup',async form=>{if(new FormData(form).get('confirm')!=='PULIHKAN')throw new Error('Ketik PULIHKAN dengan benar.');await api('/api/restore',{method:'POST',body:{...archive,confirm:'PULIHKAN'}});closeModal();await refresh();toast('Backup berhasil dipulihkan. Player menerima pembaruan konten.');});}
function parseCsv(text){const delimiter=text.split(/\r?\n/)[0].includes(';')?';':',';const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i];if(char==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(char===delimiter&&!quoted){row.push(cell.trim());cell='';}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=char;}row.push(cell.trim());if(row.some(Boolean))rows.push(row);if(rows.length<2)throw new Error('CSV harus memiliki header dan minimal satu tanggal.');const header=rows.shift().map(v=>v.toLowerCase().trim());const aliases={date:['date','tanggal'],fajr:['fajr','subuh'],dhuhr:['dhuhr','zuhur','dzuhur'],asr:['asr','asar','ashar'],maghrib:['maghrib','magrib'],isha:['isha','isya']};return rows.map(values=>Object.fromEntries(Object.entries(aliases).map(([key,names])=>[key,values[header.findIndex(h=>names.includes(h))]||''])));}
async function importPrayerFile(file){let rows;if(file.name.toLowerCase().endsWith('.json')){const parsed=JSON.parse(await file.text());rows=Array.isArray(parsed)?parsed:parsed.timetable;if(!Array.isArray(rows))throw new Error('JSON harus berisi daftar jadwal.');}else rows=parseCsv(await file.text());const fields=['fajr','dhuhr','asr','maghrib','isha'];rows=rows.map((row,index)=>{const result={date:String(row.date||'').trim()};if(/^\d{2}\/\d{2}\/\d{4}$/.test(result.date)){const [day,month,year]=result.date.split('/');result.date=`${year}-${month}-${day}`;}if(!/^\d{4}-\d{2}-\d{2}$/.test(result.date)||Number.isNaN(new Date(result.date+'T00:00:00Z').getTime()))throw new Error(`Tanggal pada baris ${index+2} tidak valid.`);for(const key of fields){const value=String(row[key]||'').trim();if(!/^([01]?\d|2[0-3]):[0-5]\d$/.test(value))throw new Error(`Waktu ${key} pada baris ${index+2} tidak valid. Gunakan HH:MM.`);const [hour,minute]=value.split(':');result[key]=`${hour.padStart(2,'0')}:${minute}`;}return result;});if(!rows.length)throw new Error('Tidak ada tanggal pada berkas.');const unique=new Map(rows.map(row=>[row.date,row]));rows=[...unique.values()].sort((a,b)=>a.date.localeCompare(b.date));if(rows.length>3660)throw new Error('Maksimal 3.660 tanggal per impor.');openModal('Impor jadwal sholat',`${rows.length} tanggal siap disimpan.`,`<div class="notice">Periode: <strong>${e(rows[0].date)}</strong> sampai <strong>${e(rows.at(-1).date)}</strong>.<br>Jadwal impor sebelumnya akan diganti. Pastikan data sesuai acuan setempat.</div>`,'Simpan jadwal impor',async()=>{const settings=clone(S.data.settings);settings.prayer||={};settings.prayer.timetable=rows;await api('/api/settings',{method:'PUT',body:settings});closeModal();await refresh();toast(`${rows.length} tanggal jadwal sholat berhasil disimpan.`);});}
function samplePrayer(){downloadBlob(new Blob(['date,fajr,dhuhr,asr,maghrib,isha\nYYYY-MM-DD,HH:MM,HH:MM,HH:MM,HH:MM,HH:MM\n'],{type:'text/csv;charset=utf-8'}),'format-jadwal-sholat.csv');toast('Isi contoh format dengan tanggal dan jadwal setempat sebelum diimpor.');}

async function handleAction(event){const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,ref=target.dataset.id;event.preventDefault();if(action==='cancel-upload'){cancelMediaUpload();return;}if(action==='close-modal'){if(previewModal.open){previewModal.close();previewModal.innerHTML='';}else closeModal();return;}if(action==='navigate'){navigate(target.dataset.view);return;}if(action.startsWith('navigate-')){navigate(action.slice(9));return;}switch(action){case 'refresh':await refresh();toast('Data diperbarui.');break;case 'logout':if(S.dirty){await leaveEditor(async()=>{await api('/api/auth/logout',{method:'POST',body:{}});S.data=null;renderAuth(await api('/api/auth/status'));});}else{await api('/api/auth/logout',{method:'POST',body:{}});S.editor=null;S.data=null;renderAuth(await api('/api/auth/status'));}break;case 'new-layout':newLayout();break;case 'edit-layout':openEditor(ref);break;case 'close-editor':navigate('layouts');break;case 'save-layout':await saveLayout();break;case 'preview-editor':await saveLayout(false);await previewLayout(S.editor.id);break;case 'preview-layout':await previewLayout(ref);break;case 'publish-layout':await publishLayout();break;case 'duplicate-layout':{const layout=await api(`/api/layouts/${encodeURIComponent(ref)}/duplicate`,{method:'POST',body:{}});await refresh(false);openEditor(layout.id);toast('Salinan layout dibuat.');break;}case 'unpublish-layout':await unpublishLayout(ref||S.editor?.id);break;case 'delete-layout':await deleteLayout(ref);break;case 'playlist-add':addPlaylistVideos();break;case 'playlist-convert':convertToPlaylist();break;case 'playlist-up':case 'playlist-down':case 'playlist-remove':changePlaylist(action,Number(ref));break;case 'add-widget':addWidget(target.dataset.type);break;case 'select-widget':S.selected=ref;updateEditorPanels();drawStage();break;case 'toggle-widget':{remember();const item=S.editor.widgets.find(w=>w.id===ref);item.enabled=item.enabled===false;markDirty();updateEditorPanels();drawStage();break;}case 'duplicate-widget':duplicateWidget();break;case 'delete-widget':deleteWidget();break;case 'raise-widget':case 'lower-widget':{const item=widget();if(item){remember();item.z=(item.z||0)+(action==='raise-widget'?1:-1);markDirty();updateEditorPanels();drawStage();}break;}case 'undo':if(S.undo.length){S.redo.push(clone(S.editor));S.editor=S.undo.pop();S.selected=null;markDirty();render();}break;case 'redo':if(S.redo.length){S.undo.push(clone(S.editor));S.editor=S.redo.pop();S.selected=null;markDirty();render();}break;case 'discard-editor':closeModal();S.discardCallback?.();S.discardCallback=null;break;case 'upload-media':document.querySelector('#media-upload')?.click();break;case 'media-filter':S.mediaFilter=target.dataset.filter;render();break;case 'view-media':viewMedia(ref);break;case 'delete-media':{const m=S.data.media.find(item=>item.id===ref);await confirmAction('Hapus media?',m?.name||'Media ini akan dihapus dari pustaka.','Hapus media',async()=>{await api(`/api/media/${encodeURIComponent(ref)}`,{method:'DELETE'});await refresh();toast('Media dihapus.');});break;}case 'pair-player':await pairPlayer();break;case 'copy-pair-code':if(navigator.clipboard){await navigator.clipboard.writeText(ref);toast('Kode pemasangan disalin.');}else toast(`Kode pemasangan: ${ref}`);break;case 'player-details':playerDetails(ref);break;case 'player-transfer':await openTransferMonitor([ref]);break;case 'player-screenshot':await requestScreenshot(ref);break;case 'refresh-screenshot':await refresh(false);updateScreenshotDialog();break;case 'player-sync':await api(`/api/players/${encodeURIComponent(ref)}/action`,{method:'POST',body:{action:'sync'}});toast('Permintaan sinkronisasi dikirim.');await refresh(false);break;case 'player-rollback':await confirmAction('Kembali ke versi sebelumnya?','Player menyiapkan versi sebelumnya lalu beralih setelah video aktif selesai.','Kembalikan versi',async()=>{await api(`/api/players/${encodeURIComponent(ref)}/action`,{method:'POST',body:{action:'rollback'}});await refresh();toast('Versi sebelumnya dikirim ke player.');});break;case 'player-clear-override':await api(`/api/players/${encodeURIComponent(ref)}/action`,{method:'POST',body:{action:'clear-override'}});toast('Player mengikuti jadwal aktif kembali.');await refresh(false);break;case 'player-revoke':await confirmAction('Cabut akses player?','Player ini perlu dipasangkan kembali untuk terhubung ke server.','Cabut akses',async()=>{await api(`/api/players/${encodeURIComponent(ref)}/action`,{method:'POST',body:{action:'revoke'}});await refresh();toast('Akses player dicabut.');});break;case 'delete-player':await confirmAction('Hapus player dari daftar?','Identitas perangkat akan dilepas dari server.','Hapus player',async()=>{await api(`/api/players/${encodeURIComponent(ref)}`,{method:'DELETE'});await refresh();toast('Player dihapus.');});break;case 'new-schedule':scheduleModal();break;case 'edit-schedule':scheduleModal(ref);break;case 'delete-schedule':await confirmAction('Hapus jadwal?','Player akan menerima daftar jadwal yang diperbarui.','Hapus jadwal',async()=>{await api(`/api/schedules/${encodeURIComponent(ref)}`,{method:'DELETE'});await refresh();toast('Jadwal dihapus.');});break;case 'backup':await downloadBackup();break;case 'restore':document.querySelector('#restore-file').click();break;case 'import-prayer':document.querySelector('#prayer-import').click();break;case 'sample-prayer':samplePrayer();break;case 'clear-prayer':await confirmAction('Hapus jadwal sholat impor?','Perhitungan lokal akan dipakai sebagai cadangan.','Hapus jadwal impor',async()=>{const settings=clone(S.data.settings);settings.prayer.timetable=[];await api('/api/settings',{method:'PUT',body:settings});await refresh();toast('Jadwal impor dihapus.');});break;}}

app.addEventListener('click',event=>handleAction(event).catch(report));
modal.addEventListener('click',event=>handleAction(event).catch(report));
previewModal.addEventListener('click',event=>handleAction(event).catch(report));
modal.addEventListener('close',()=>{if(!modal.open){modal.querySelectorAll('video').forEach(video=>video.pause());S.screenshotPlayer=null;S.transferMonitor=null;}});
previewModal.addEventListener('close',()=>{previewModal.innerHTML='';});
document.addEventListener('submit',async event=>{const form=event.target;if(!['auth-form','modal-form','settings-form'].includes(form.id))return;event.preventDefault();const submit=form.querySelector('button[type=submit]')||form.querySelector('button:not([type])');if(submit)submit.disabled=true;try{if(form.id==='auth-form'){const data=Object.fromEntries(new FormData(form));const result=await api(S.auth.initialized?'/api/auth/login':'/api/auth/setup',{method:'POST',body:data});S.auth={initialized:true,authenticated:true,user:result.user||{username:data.username}};await refresh();}else if(form.id==='modal-form'){modalError('');await S.modalHandler?.(form);}else{const data=new FormData(form),settings=clone(S.data.settings);settings.locationName=String(data.get('locationName')).trim();settings.timezone=data.get('timezone');settings.latitude=Number(data.get('latitude'));settings.longitude=Number(data.get('longitude'));settings.prayer||={};settings.prayer.method='Kemenag';settings.prayer.adjustments=Object.fromEntries(['fajr','dhuhr','asr','maghrib','isha'].map(key=>[key,Number(data.get('adjust-'+key))]));await api('/api/settings',{method:'PUT',body:settings});await refresh();toast('Pengaturan disimpan dan dikirim ke player.');}}catch(error){if(form.id==='auth-form')document.querySelector('#auth-error').textContent=error.message;else if(form.id==='modal-form')modalError(error.message);else report(error);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('input',event=>{const input=event.target;if(input.id==='page-search'){S.search=input.value;const position=input.selectionStart;render();const next=document.querySelector('#page-search');next?.focus();next?.setSelectionRange(position,position);return;}if(input.id==='layout-name'){if(S.editor){S.editor.name=input.value;markDirty();}return;}if(!S.editor)return;if(input.dataset.layoutProp){const prop=input.dataset.layoutProp;S.editor[prop]=prop==='duration'?Math.max(1,Number(input.value)||30):input.value;markDirty();drawStage();return;}if(input.dataset.prop){const item=widget();if(!item)return;const prop=input.dataset.prop;if(['enabled','muted','mediaId','fallbackMediaId','fit','align','fontWeight','playlist'].includes(prop))return;if(input.type==='number'||input.type==='range'){if(input.value==='')return;item[prop]=Number(input.value);if(['width','height'].includes(prop))item[prop]=Math.max(10,item[prop]);}else item[prop]=input.value;markDirty();drawStage();const layers=document.querySelector('#layers-list');if(prop==='name'&&layers)layers.innerHTML=layersMarkup();}});
document.addEventListener('change',event=>{const input=event.target;if(input.id==='media-upload'){const files=[...input.files];input.value='';uploadFiles(files).catch(report);return;}if(input.id==='restore-file'){if(input.files[0])restoreFromFile(input.files[0]).catch(report);input.value='';return;}if(input.id==='prayer-import'){if(input.files[0])importPrayerFile(input.files[0]).catch(report);input.value='';return;}if(input.id==='schedule-repeat'){modal.querySelector('#schedule-days-field').hidden=input.value!=='weekly';modal.querySelector('#schedule-until-field').hidden=input.value==='once';return;}if(input.id==='layout-resolution'&&S.editor){remember();const [width,height]=input.value.split('x').map(Number);const ratioX=width/S.editor.width,ratioY=height/S.editor.height;for(const item of S.editor.widgets){for(const prop of ['x','width'])item[prop]=Math.round(item[prop]*ratioX);for(const prop of ['y','height'])item[prop]=Math.round(item[prop]*ratioY);if(item.fontSize)item.fontSize=Math.round(item.fontSize*Math.min(ratioX,ratioY));}S.editor.width=width;S.editor.height=height;markDirty();render();return;}if(input.hasAttribute('data-playlist-muted')&&S.editor){const item=widget(),index=Number(input.dataset.playlistMuted);if(!isVideoPlaylist(item)||!Number.isInteger(index)||!item.playlist[index])return;remember();item.playlist[index].muted=input.checked;delete item.mediaId;markDirty();drawStage();return;}if(input.dataset.prop&&S.editor){const item=widget();if(!item)return;const prop=input.dataset.prop;if(!['enabled','muted','mediaId','fallbackMediaId','fit','align','fontWeight','playlist'].includes(prop))return;remember();if(input.type==='checkbox')item[prop]=input.checked;else if(prop==='playlist')item.playlist=[...input.selectedOptions].map(option=>({mediaId:option.value,duration:10}));else if(prop==='fontWeight')item[prop]=Number(input.value);else item[prop]=input.value;if(prop==='mediaId')delete item.playlist;markDirty();updateEditorPanels();drawStage();}});
document.addEventListener('focusin',event=>{if(S.editor&&(event.target.dataset.prop||event.target.dataset.layoutProp))remember();});
document.addEventListener('pointerdown',event=>{if(!S.editor||event.button!==0)return;const box=event.target.closest('[data-widget]');const stage=document.querySelector('#canvas-stage');if(!box){if(event.target===document.querySelector('#canvas-overlays')){S.selected=null;updateEditorPanels();drawStage();}return;}event.preventDefault();const item=S.editor.widgets.find(w=>w.id===box.dataset.widget);if(!item)return;S.selected=item.id;remember();const rect=stage.getBoundingClientRect();S.drag={id:item.id,startX:event.clientX,startY:event.clientY,x:item.x,y:item.y,width:item.width,height:item.height,scaleX:S.editor.width/rect.width,scaleY:S.editor.height/rect.height,resize:Boolean(event.target.closest('[data-resize]'))};document.body.setPointerCapture?.(event.pointerId);updateEditorPanels();drawStage();});
document.addEventListener('pointermove',event=>{if(!S.drag||!S.editor)return;const drag=S.drag,item=S.editor.widgets.find(w=>w.id===drag.id);if(!item)return;const dx=(event.clientX-drag.startX)*drag.scaleX,dy=(event.clientY-drag.startY)*drag.scaleY;if(drag.resize){item.width=Math.round(Math.max(10,Math.min(S.editor.width-item.x,drag.width+dx)));item.height=Math.round(Math.max(10,Math.min(S.editor.height-item.y,drag.height+dy)));}else{item.x=Math.round(Math.max(0,Math.min(S.editor.width-item.width,drag.x+dx)));item.y=Math.round(Math.max(0,Math.min(S.editor.height-item.height,drag.y+dy)));}markDirty();drawStage();});
document.addEventListener('pointerup',()=>{if(S.drag){S.drag=null;updateEditorPanels();}});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.matches('.layout-preview,.layer')){event.target.click();return;}if(!S.editor||modal.open||previewModal.open)return;const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName)||event.target.isContentEditable;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();saveLayout().catch(report);return;}if(typing)return;if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();deleteWidget();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'){event.preventDefault();duplicateWidget();}const item=widget();if(item&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();remember();const n=event.shiftKey?10:1;item.x=Math.max(0,Math.min(S.editor.width-item.width,item.x+(event.key==='ArrowRight'?n:event.key==='ArrowLeft'?-n:0)));item.y=Math.max(0,Math.min(S.editor.height-item.height,item.y+(event.key==='ArrowDown'?n:event.key==='ArrowUp'?-n:0)));markDirty();updateEditorPanels();drawStage();}});
window.addEventListener('beforeunload',event=>{if(S.dirty){event.preventDefault();event.returnValue='';}});

async function init(){try{S.auth=await api('/api/auth/status');if(!S.auth.authenticated){renderAuth(S.auth);return;}await refresh();}catch(error){app.innerHTML=`<div class="initial-loader"><div class="empty-icon">${icon('info')}</div><h2>Server belum dapat dihubungi</h2><p class="muted">${e(error.message)}</p><button class="btn primary" id="retry-init">Coba lagi</button></div>`;document.querySelector('#retry-init').addEventListener('click',init);}}
setInterval(async()=>{if(S.polling||!S.data||!S.auth?.authenticated||document.hidden)return;const now=Date.now(),liveView=!S.editor&&!modal.open&&!previewModal.open&&['overview','players'].includes(S.view),fast=Boolean(S.transferMonitor&&modal.open)||liveView;if(now-S.lastPollAt<(fast?2000:10000))return;S.lastPollAt=now;S.polling=true;try{const focusedControl=document.activeElement?.closest('button,input,select,textarea,a'),repaint=!mediaUpload&&liveView&&!focusedControl&&now-S.lastViewRenderAt>=10000;await refresh(repaint);if(repaint)S.lastViewRenderAt=now;}catch(error){if(error.status===401){if(modal.open)closeModal();S.editor=null;S.data=null;renderAuth(await api('/api/auth/status'));}}finally{S.polling=false;}},2000);
init();
